function aggregate(){display=[];for(let i=0;i<bars.length;i+=tf){const a=bars.slice(i,i+tf),end=i+a.length-1;display.push({time:a[0].time,open:a[0].open,high:Math.max(...a.map(b=>b.high)),low:Math.min(...a.map(b=>b.low)),close:a.at(-1).close,volume:a.reduce((s,b)=>s+b.volume,0),fast:result.ind.fast[end],slow:result.ind.slow[end],originalStart:i,originalEnd:end});}view.end=Math.min(display.length,view.end);view.count=Math.min(display.length,Math.max(10,view.count));}
