function setupCanvas(id){const canvas=$(id),rect=canvas.getBoundingClientRect(),dpr=window.devicePixelRatio||1;canvas.width=Math.round(rect.width*dpr);canvas.height=Math.round(rect.height*dpr);const ctx=canvas.getContext('2d');ctx.scale(dpr,dpr);return {ctx,w:rect.width,h:rect.height};}
function drawChart(){if(!result||!display.length)return;const {ctx,w,h}=setupCanvas('chart');if(w<1)return;const left=16,right=78,top=16,bottom=29,plotW=w-left-right,plotH=h-top-bottom;view.count=Math.min(display.length,Math.max(10,Math.round(view.count)));view.end=Math.max(view.count,Math.min(display.length,Math.round(view.end)));const start=view.end-view.count,a=display.slice(start,view.end);let hi=-Infinity,lo=Infinity;for(const b of a){hi=Math.max(hi,b.high,b.fast??-Infinity,b.slow??-Infinity);lo=Math.min(lo,b.low,b.fast??Infinity,b.slow??Infinity);}const pad=(hi-lo)*.08||hi*.01;hi+=pad;lo-=pad;const y=p=>top+(hi-p)/(hi-lo)*plotH*.85,x=i=>left+(i+.5)/a.length*plotW,cw=plotW/a.length;ctx.font='11px ui-monospace, monospace';ctx.lineWidth=1;for(let i=0;i<6;i++){const p=lo+(hi-lo)*i/5,yy=y(p);ctx.strokeStyle='#242a35';ctx.beginPath();ctx.moveTo(left,yy);ctx.lineTo(w-right,yy);ctx.stroke();ctx.fillStyle='#7f8ba0';ctx.fillText(money(p,p<10?4:0),w-right+10,yy+4);}const maxV=a.reduce((m,b)=>Math.max(m,b.volume),1);a.forEach((b,i)=>{const xx=x(i),color=b.close>=b.open?'#39cba2':'#e86f80';ctx.fillStyle=color+'38';ctx.fillRect(xx-cw*.3,h-bottom-plotH*.12*b.volume/maxV,Math.max(1,cw*.6),plotH*.12*b.volume/maxV);ctx.strokeStyle=color;ctx.beginPath();ctx.moveTo(xx,y(b.high));ctx.lineTo(xx,y(b.low));ctx.stroke();ctx.fillStyle=color;ctx.fillRect(xx-cw*.3,Math.min(y(b.open),y(b.close)),Math.max(1,cw*.6),Math.max(1,Math.abs(y(b.close)-y(b.open))));});for(const [key,color] of [['fast','#839cff'],['slow','#dbb564']]){ctx.strokeStyle=color;ctx.lineWidth=1.5;ctx.beginPath();let active=false;a.forEach((b,i)=>{if(b[key]===null){active=false;return;}if(active)ctx.lineTo(x(i),y(b[key]));else ctx.moveTo(x(i),y(b[key]));active=true;});ctx.stroke();}for(const t of result.trades){for(const [index,price,entry] of [[t.entryIndex,t.entry,true],[t.exitIndex,t.exit,false]]){const j=Math.floor(index/tf)-start;if(j>=0&&j<a.length){ctx.fillStyle=entry?'#72afff':'#eaae61';const xx=x(j),yy=y(price);ctx.beginPath();ctx.moveTo(xx,yy);ctx.lineTo(xx-4,yy+(entry?8:-8));ctx.lineTo(xx+4,yy+(entry?8:-8));ctx.closePath();ctx.fill();}}}ctx.fillStyle='#7f8ba0';ctx.textAlign='center';for(let i=0;i<5;i++){const ix=Math.round(i*(a.length-1)/4);ctx.fillText(new Date(a[ix].time*1000).toISOString().slice(5,16).replace('T',' '),Math.max(45,Math.min(w-right-30,x(ix))),h-8);}ctx.textAlign='left';const last=a.at(-1),yy=y(last.close);ctx.setLineDash([3,4]);ctx.strokeStyle=last.close>=last.open?'#39cba277':'#e86f8077';ctx.beginPath();ctx.moveTo(left,yy);ctx.lineTo(w-right,yy);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle=last.close>=last.open?'#39cba2':'#e86f80';ctx.fillRect(w-right+2,yy-10,76,20);ctx.fillStyle='#101319';ctx.fillText(money(last.close,last.close<10?4:0),w-right+7,yy+4);$('dateRange').textContent=dt(a[0].time).slice(0,10)+' — '+dt(a.at(-1).time).slice(0,10);}
function drawEquity(){if(!result||$('overview').hidden)return;const {ctx,w,h}=setupCanvas('equityChart'),a=result.equity;if(!w)return;const left=24,right=78,top=12,bottom=22,values=a.map(e=>curve==='equity'?e.value:e.drawdown);let lo=values.reduce((m,v)=>Math.min(m,v),Infinity),hi=values.reduce((m,v)=>Math.max(m,v),-Infinity);const pad=(hi-lo)*.15||1;lo-=pad;hi+=pad;const x=i=>left+i/(a.length-1)*(w-left-right),y=v=>top+(hi-v)/(hi-lo)*(h-top-bottom);ctx.font='11px ui-monospace,monospace';for(let i=0;i<3;i++){const v=lo+(hi-lo)*i/2,yy=y(v);ctx.strokeStyle='#242a35';ctx.beginPath();ctx.moveTo(left,yy);ctx.lineTo(w-right,yy);ctx.stroke();ctx.fillStyle='#7f8ba0';ctx.fillText(money(v,curve==='equity'?0:1)+(curve==='equity'?'':'%'),w-right+8,yy+4);}const color=curve==='equity'?'#39d3a2':'#f37c86';ctx.beginPath();values.forEach((v,i)=>i?ctx.lineTo(x(i),y(v)):ctx.moveTo(x(i),y(v)));ctx.strokeStyle=color;ctx.lineWidth=1.7;ctx.stroke();ctx.lineTo(x(a.length-1),h-bottom);ctx.lineTo(left,h-bottom);ctx.closePath();const gradient=ctx.createLinearGradient(0,top,0,h);gradient.addColorStop(0,color+'30');gradient.addColorStop(1,color+'00');ctx.fillStyle=gradient;ctx.fill();}
$('chart').addEventListener('wheel',e=>{e.preventDefault();view.count*=e.deltaY>0?1.15:.85;drawChart();},{passive:false});$('chart').onpointerdown=e=>{drag={x:e.clientX,end:view.end};$('chart').setPointerCapture(e.pointerId);};$('chart').onpointermove=e=>{if(drag){view.end=drag.end-(e.clientX-drag.x)/$('chart').clientWidth*view.count;drawChart();return;}const rect=$('chart').getBoundingClientRect(),i=Math.floor((e.clientX-rect.left-16)/(rect.width-94)*view.count)+view.end-view.count,b=display[i];if(!b)return;$('crosshair').hidden=false;$('crosshair').textContent=`${dt(b.time)}  O ${priceMoney(b.open)} H ${priceMoney(b.high)} L ${priceMoney(b.low)} C ${priceMoney(b.close)}`;};$('chart').onpointerup=$('chart').onpointercancel=()=>drag=null;$('chart').onpointerleave=()=>{$('crosshair').hidden=true;};$('resetView').onclick=()=>{view={count:display.length,end:display.length};drawChart();};
document.querySelectorAll('[data-tf]').forEach(b=>b.onclick=()=>{tf=Number(b.dataset.tf);document.querySelectorAll('[data-tf]').forEach(x=>x.classList.toggle('active',x===b));view={count:150,end:Math.ceil(bars.length/tf)};aggregate();drawChart();});document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-tab]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-selected',String(x===b));});document.querySelectorAll('.tab-panel').forEach(x=>x.hidden=x.id!==b.dataset.tab);drawEquity();});document.querySelectorAll('[data-curve]').forEach(b=>b.onclick=()=>{curve=b.dataset.curve;document.querySelectorAll('[data-curve]').forEach(x=>x.classList.toggle('active',x===b));drawEquity();});
const ro=new ResizeObserver(()=>{drawChart();drawEquity();});ro.observe($('chart').parentElement);ro.observe($('overview'));
function updateData(){resetOptimizer();const last=bars.at(-1),prev=bars.at(-2),change=(last.close/prev.close-1)*100;$('symbol').textContent=dataName;$('source').textContent=(marketMeta?marketMeta.provider+' · '+INTERVALS[marketMeta.interval].label:isSample?'Synthetic sample':'Imported OHLCV')+' · '+bars.length.toLocaleString()+' candles';$('dataBadge').textContent=marketMeta?'FETCHED DATA':isSample?'SAMPLE DATA':'IMPORTED DATA';$('lastPrice').textContent=priceMoney(last.close);$('priceChange').textContent=(change>=0?'+':'')+money(change)+'%';$('priceChange').className=change>=0?'positive':'negative';view={count:150,end:Math.ceil(bars.length/tf)};$('capitalLabel').textContent='Initial capital, '+quoteCurrency();$('assetIcon').textContent=marketMeta?.market==='forex'?'FX':marketMeta?.market==='commodities'?'CM':({'BTC/USDT':'₿','XRP/USDT':'XRP','SOL/USDT':'SOL','ETH/USDT':'Ξ'}[marketMeta?.symbol]||'₿');$('priceChange').title='Change from the previous completed candle';refreshFreshness();run();syncQuickAssets();$('exportMarket').disabled=isSample;}
function download(name,text,type='text/csv'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('export').onclick=()=>download('striangle-trades.csv','entry_time,exit_time,entry_price,exit_price,quantity,pnl,return_pct,reason\n'+result.trades.map(t=>[dt(t.entryTime)+'Z',dt(t.exitTime)+'Z',t.entry,t.exit,t.qty,t.pnl,t.return,t.reason].join(',')).join('\n'));
$('downloadSample').onclick=()=>download('striangle-synthetic-sample.csv','time,open,high,low,close,volume\n'+demoData().map(b=>[new Date(b.time*1000).toISOString(),b.open,b.high,b.low,b.close,b.volume].join(',')).join('\n'));
async function openDB(){return new Promise((resolve,reject)=>{const r=indexedDB.open('striangle',1);r.onupgradeneeded=()=>r.result.createObjectStore('state');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}async function persist(value){if(!db)return;return new Promise((resolve,reject)=>{const tx=db.transaction('state','readwrite');tx.objectStore('state').put(value,'dataset');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});}
$('import').onclick=()=>$('file').click();$('file').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>20*1024*1024)throw Error('CSV must be smaller than 20 MB.');const next=parseCSV(await f.text());backtest(next,config());cancelMarket();marketMeta=null;bars=next;dataName=f.name.replace(/\.csv$/i,'').slice(0,35);isSample=false;updateData();try{await persist({bars,dataName,isSample,marketMeta});}catch{status('Data imported; browser storage is full. This dataset will not persist.',true);}}catch(err){status(err.message,true);}e.target.value='';};
$('restoreSample').onclick=async()=>{cancelMarket();marketMeta=null;bars=demoData();dataName='BTC / USD';isSample=true;updateData();try{await persist({bars,dataName,isSample,marketMeta});}catch{status('Sample restored; browser storage unavailable.',true);}};
$('save').onclick=()=>{try{const c=config();backtest(bars,c);localStorage.setItem('striangle-strategy',JSON.stringify(c));status('Strategy saved in this browser.');}catch(e){status(e.message,true);}};
function applyConfig(c){for(const k of numeric)if(c[k]!=null)$(k).value=c[k];$('name').value=c.name||'My strategy';$('strategy').value=c.strategy||'cross';for(const [id,r] of [['entryRule',c.entry],['exitRule',c.exit]])if(r){for(const key of ['left','op','right','value'])$(id).querySelector('.'+key).value=r[key];$(id).querySelector('.right').onchange();}syncMode();}
$('load').onclick=()=>{try{const s=localStorage.getItem('striangle-strategy');if(!s){status('No saved strategy yet.');return;}applyConfig(JSON.parse(s));run();}catch{status('Saved strategy could not be loaded.',true);}};
$('help').onclick=()=>$('helpDialog').showModal();$('closeHelp').onclick=()=>$('helpDialog').close();
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredPrompt=e;$('install').hidden=false;});$('install').onclick=async()=>{if(!deferredPrompt)return;await deferredPrompt.prompt();deferredPrompt=null;$('install').hidden=true;};window.addEventListener('appinstalled',()=>{$('install').hidden=true;});function connection(){ $('connection').textContent=navigator.onLine?'Local workspace':'Offline mode';}window.addEventListener('online',connection);window.addEventListener('offline',connection);connection();
if('serviceWorker' in navigator){const hadController=!!navigator.serviceWorker.controller;let reloading=false;navigator.serviceWorker.addEventListener('controllerchange',()=>{if(hadController&&!reloading){reloading=true;location.reload();}});navigator.serviceWorker.register('./sw.js').catch(()=>{$('connection').textContent='Offline setup unavailable';});}
function marketStatus(text,error=false){$('marketStatus').textContent=text;$('marketStatus').classList.toggle('negative',error);}
function refreshFreshness(){
  if(!marketMeta){$('dataFreshness').textContent='';return;}
  const fetched=dt(marketMeta.fetchedAt/1000),last=dt(marketMeta.lastCandle);
  $('dataFreshness').textContent=`${navigator.onLine?'Saved snapshot':'Offline snapshot'} · Fetched ${fetched} UTC · Last candle opened ${last} UTC · ${quoteCurrency()} quote · ${marketMeta.provider==='Twelve Data'?'Newest provider candle omitted. ':''}Fetch again to update.`;
}
function populateMarket(){
  const market=$('market').value;
  $('marketSymbols').replaceChildren(...MARKETS[market].map(([symbol,label])=>{const o=document.createElement('option');o.value=symbol;o.label=label;return o;}));
  $('marketSymbol').value=MARKETS[market][0][0];
  $('apiKeySettings').hidden=market==='crypto';
  $('quickAssets').hidden=market!=='crypto';
  for(const option of $('marketCount').options) option.disabled=market!=='crypto'&&Number(option.value)>5000;
  if(market!=='crypto'&&Number($('marketCount').value)>5000) $('marketCount').value='5000';
  marketStatus(market==='crypto'?'Binance public spot candles · no API key needed.':'Twelve Data · your API key is required. Availability and delay depend on your plan.');
}
function busyMarket(busy){$('fetchMarket').disabled=busy;$('fetchMarket').textContent=busy?'Fetching…':'↓ Fetch candles';$('cancelFetch').hidden=!busy;}
function cancelMarket(){if(marketRequest){marketRequest.abort();marketRequest=null;marketSequence++;busyMarket(false);marketStatus('Fetch cancelled. Existing data retained.');}}
$('cancelFetch').onclick=cancelMarket;
$('market').onchange=()=>{cancelMarket();populateMarket();};
for(const id of ['marketSymbol','marketInterval','marketCount','marketApiKey'])$(id).addEventListener('input',cancelMarket);
$('clearKey').onclick=()=>{cancelMarket();$('marketApiKey').value='';marketStatus('API key cleared from this page.');};
async function loadMarket(){
  cancelMarket();const sequence=++marketSequence,controller=new AbortController();marketRequest=controller;
  const settings={market:$('market').value,symbol:$('marketSymbol').value,interval:$('marketInterval').value,count:Number($('marketCount').value),apiKey:$('marketApiKey').value,signal:controller.signal};
  busyMarket(true);marketStatus('Fetching completed candles… Your current chart stays available.');
  try{
    const next=await fetchMarket({...settings,onProgress:progress=>{if(sequence===marketSequence)marketStatus(`${settings.symbol} · ${progress.received.toLocaleString()} / ${progress.requested.toLocaleString()} completed candles · ${progress.pages} pages`);}});
    if(sequence!==marketSequence)return;
    backtest(next.bars,config());
    bars=next.bars;dataName=next.dataName;isSample=false;marketMeta=next.marketMeta;updateData();
    marketStatus(`${marketMeta.provider} · Loaded ${bars.length.toLocaleString()} completed candles for ${dataName}.`);
    try{await persist({bars,dataName,isSample,marketMeta});}catch{marketStatus('Candles loaded, but browser storage is full. They will not persist.',true);}
  }catch(e){if(sequence===marketSequence)marketStatus(e.message+' Existing chart data retained.',true);}
  finally{if(sequence===marketSequence){marketRequest=null;busyMarket(false);}}
}
$('marketForm').onsubmit=e=>{e.preventDefault();loadMarket();};
function syncQuickAssets(){for(const button of document.querySelectorAll('[data-asset]'))button.setAttribute('aria-pressed',String(marketMeta?.market==='crypto'&&marketMeta.symbol===button.dataset.asset));}
for(const button of document.querySelectorAll('[data-asset]'))button.onclick=()=>{cancelMarket();$('market').value='crypto';populateMarket();$('marketSymbol').value=button.dataset.asset;loadMarket();};
$('exportMarket').onclick=()=>download(`striangle-${dataName.replace(/[^A-Za-z0-9]/g,'-')}-${marketMeta?.interval||'candles'}.csv`,'time,open,high,low,close,volume\n'+bars.map(b=>[new Date(b.time*1000).toISOString(),b.open,b.high,b.low,b.close,b.volume].join(',')).join('\n'));

window.addEventListener('online',refreshFreshness);window.addEventListener('offline',refreshFreshness);
const optimizerFields=[['fast','Fast SMA','10,20,30'],['slow','Slow SMA','40,60,80'],['rsiPeriod','RSI period','7,14,21'],['oversold','RSI entry','25,30'],['overbought','RSI exit','65,70'],['stop','Stop loss, %','2,3,5'],['take','Take profit, %','4,6,10'],['entryValue','Custom entry number',''],['exitValue','Custom exit number','']];
for(const [key,title,value] of optimizerFields){const label=document.createElement('label');label.textContent=title;const input=document.createElement('input');input.id='range_'+key;input.value=value;input.placeholder='Current value';input.autocomplete='off';label.append(input);$('optimizerRanges').append(label);}
function optimizerSpec(){return {families:[...document.querySelectorAll('[name="family"]:checked')].map(e=>e.value),ranges:Object.fromEntries(optimizerFields.map(([key])=>[key,$('range_'+key).value])),holdout:Number($('optimizerHoldout').value)};}
function optimizerStatus(text,error=false){$('optimizerStatus').textContent=text;$('optimizerStatus').classList.toggle('negative',error);}
function optimizerEstimate(){try{const grid=buildGrid(config(),optimizerSpec());const work=grid.configs.length*bars.length;$('optimizerEstimate').textContent=grid.configs.length.toLocaleString()+' valid combinations · '+grid.skipped+' incompatible combinations skipped · '+(work/1000000).toFixed(1)+' million candle evaluations'+(work>WORK_LIMIT?' — reduce ranges or data length.':'.');}catch(e){$('optimizerEstimate').textContent=e.message;}}
function optimizerBusy(busy){$('optimizerRun').disabled=busy;$('optimizerCancel').hidden=!busy;$('optimizerRun').textContent=busy?'Searching…':'▶ Run combinations';}
function resetOptimizer(){if(optimizerWorker){optimizerWorker.terminate();optimizerWorker=null;}optimizerResults=[];optimizerSnapshot=null;optimizerCompleted=0;optimizerBusy(false);$('optimizerExport').disabled=true;$('optimizerRows').replaceChildren();$('optimizerContext').textContent='';$('optimizerProgress').value=0;optimizerStatus('Dataset ready. Run combinations to compare strategies.');optimizerEstimate();}
function parameterLabel(c){const signal=c.strategy==='cross'?`SMA ${c.fast}/${c.slow}`:c.strategy==='rsi'?`RSI ${c.rsiPeriod} · ${c.oversold}/${c.overbought}`:`Custom · SMA ${c.fast}/${c.slow} · RSI ${c.rsiPeriod} · entry ${c.entry.left} ${c.entry.op} ${c.entry.right==='number'?c.entry.value:c.entry.right} · exit ${c.exit.left} ${c.exit.op} ${c.exit.right==='number'?c.exit.value:c.exit.right}`;return `${signal} · SL ${c.stop}% / TP ${c.take}%`;}
function showOptimizerResults(){
  let sorted;try{sorted=rank(optimizerResults,$('optimizerMetric').value,Number($('optimizerMinTrades').value));}catch(e){optimizerStatus(e.message,true);return;}
  $('optimizerRows').replaceChildren();
  for(const [i,row] of sorted.slice(0,50).entries()){
    const tr=document.createElement('tr');
    const vals=[i+1,parameterLabel(row.config),money(row.train.netPct)+'%',money(row.train.maxDD)+'%',row.train.trades,money(row.train.winRate,1)+'%',Number.isFinite(row.train.profitFactor)?money(row.train.profitFactor):'∞',row.holdout?money(row.holdout.netPct)+'%':'—',row.holdout?.trades??'—'];
    vals.forEach((v,j)=>{const td=document.createElement('td');td.textContent=v;if(j===2)td.className=row.train.netPct>=0?'positive':'negative';if(j===7&&row.holdout)td.className=row.holdout.netPct>=0?'positive':'negative';tr.append(td);});
    const td=document.createElement('td'),button=document.createElement('button');button.textContent='Load';button.type='button';button.onclick=()=>{applyConfig({...row.config,name:parameterLabel(row.config).slice(0,70)});run();document.querySelector('[data-tab="overview"]').click();status('Loaded optimizer settings · full-dataset backtest shown.');};td.append(button);tr.append(td);$('optimizerRows').append(tr);
  }
  if(!sorted.length){const tr=document.createElement('tr'),td=document.createElement('td');td.colSpan=10;td.textContent=optimizerResults.length?'No combinations meet the minimum training-trade filter.':'Waiting for completed combinations.';tr.append(td);$('optimizerRows').append(tr);}
  $('optimizerExport').disabled=!optimizerResults.length;
  if(optimizerSnapshot)$('optimizerContext').textContent=optimizerSnapshot.label+` · Showing ${Math.min(50,sorted.length)} of ${sorted.length.toLocaleString()} eligible results. Export includes all ${optimizerResults.length.toLocaleString()} completed combinations.`;
}
$('optimizerForm').addEventListener('input',optimizerEstimate);
$('strategyForm').addEventListener('input',optimizerEstimate);
for(const id of ['optimizerMetric','optimizerMinTrades'])$(id).addEventListener('input',showOptimizerResults);
$('optimizerForm').onsubmit=e=>{
 e.preventDefault();
 try{
  const base=config(),spec=optimizerSpec(),grid=buildGrid(base,spec),segments=splitBars(bars,spec.holdout);
  rank([],$('optimizerMetric').value,Number($('optimizerMinTrades').value));
  if(grid.configs.length*bars.length>WORK_LIMIT)throw Error('Search exceeds 50 million candle evaluations. Reduce ranges or history.');
  if(!window.Worker)throw Error('This browser does not support background strategy searches.');
  optimizerWorker?.terminate();optimizerResults=[];optimizerCompleted=0;
  optimizerSnapshot={dataName,marketMeta,isSample,quote:quoteCurrency(),spec,base,trainStart:segments.train[0].time,trainEnd:segments.train.at(-1).time,holdoutStart:segments.holdout[0]?.time,holdoutEnd:segments.holdout.at(-1)?.time,label:`${dataName}${isSample?' (synthetic sample)':''} · Training ${dt(segments.train[0].time)} to ${dt(segments.train.at(-1).time)} UTC · ${spec.holdout?'Holdout '+spec.holdout+'% ('+segments.holdout.length+' candles, independent warmup)':'No holdout'} · ${quoteCurrency()} · Fee ${base.fee}% / slippage ${base.slippage}%`};
  $('optimizerProgress').max=grid.configs.length;$('optimizerProgress').value=0;optimizerBusy(true);showOptimizerResults();optimizerStatus(`Searching ${grid.configs.length.toLocaleString()} combinations…`);
  const worker=new Worker(new URL('./optimizer-worker.mjs',import.meta.url),{type:'module'});optimizerWorker=worker;
  worker.onmessage=({data})=>{
   if(worker!==optimizerWorker)return;
   if(data.type==='batch'){optimizerResults.push(...data.rows);optimizerCompleted=data.completed;$('optimizerProgress').value=data.completed;optimizerStatus(`${data.completed.toLocaleString()} / ${data.total.toLocaleString()} combinations tested`);showOptimizerResults();}
   if(data.type==='done'||data.type==='error'){worker.terminate();optimizerWorker=null;optimizerBusy(false);optimizerStatus(data.type==='done'?`Finished · ${data.total.toLocaleString()} combinations tested. Ranked on training data only.`:data.message+' Completed results retained.',data.type==='error');showOptimizerResults();}
  };
  worker.onerror=()=>{if(worker!==optimizerWorker)return;worker.terminate();optimizerWorker=null;optimizerBusy(false);optimizerStatus('Search worker failed. Completed results retained; try fewer combinations.',true);};
  worker.postMessage({bars,base,spec});
 }catch(err){optimizerWorker?.terminate();optimizerWorker=null;optimizerBusy(false);optimizerStatus(err.message,true);}
};
$('optimizerCancel').onclick=()=>{optimizerWorker?.terminate();optimizerWorker=null;optimizerBusy(false);optimizerStatus(`Stopped · ${optimizerCompleted.toLocaleString()} completed combinations retained. Results are partial.`);showOptimizerResults();};
$('optimizerExport').onclick=()=>{
 const columns=['id','dataset','source','quote_currency','training_start_utc','training_end_utc','holdout_start_utc','holdout_end_utc','strategy','fast','slow','rsi_period','rsi_entry','rsi_exit','stop_pct','take_pct','capital','size_pct','fee_pct','slippage_pct','entry_rule','exit_rule','train_return_pct','train_net','train_drawdown_pct','train_trades','train_win_pct','train_profit_factor','holdout_return_pct','holdout_drawdown_pct','holdout_trades'];
 const escape=v=>'"'+String(v??'').replace(/^[=+@-]/,"'" ).replaceAll('"','""')+'"';
 const csv=optimizerResults.map(r=>{const c=r.config,s=optimizerSnapshot;return [r.id,s.dataName,s.marketMeta?.provider||(s.isSample?'synthetic':'CSV'),s.quote,dt(s.trainStart),dt(s.trainEnd),s.holdoutStart?dt(s.holdoutStart):'',s.holdoutEnd?dt(s.holdoutEnd):'',c.strategy,c.fast,c.slow,c.rsiPeriod,c.oversold,c.overbought,c.stop,c.take,c.capital,c.size,c.fee,c.slippage,JSON.stringify(c.entry),JSON.stringify(c.exit),r.train.netPct,r.train.net,r.train.maxDD,r.train.trades,r.train.winRate,r.train.profitFactor,r.holdout?.netPct,r.holdout?.maxDD,r.holdout?.trades].map(v=>typeof v==='number'?String(v):escape(v)).join(',');});
 download('striangle-optimizer-results.csv',columns.join(',')+'\n'+csv.join('\n'));
};
